import threading

class FileStore:
    def __init__(self):
        self.handles = {}
        self.cache = {}
        self.lock = threading.Lock()

    def open_for_read(self, path):
        with self.lock:
            handle = self.handles.get(path)
            if handle is None:
                handle = open(path, "rb")
                self.handles[path] = handle
            return handle

    def read(self, path):
        handle = self.open_for_read(path)
        data = handle.read()
        self.cache[path] = data
        return data

    def close(self, path):
        with self.lock:
            handle = self.handles.pop(path, None)
            if handle is not None:
                handle.close()
